import { posix } from 'node:path';
import { stringLiteralOf } from './literals.ts';

/** Which cf-loom command writes a generated file, as its first line says. */
export type GeneratingCommand = 'generate' | 'package';

/** The first line of every file a command regenerates, so nobody edits it. */
export function headerOf(command: GeneratingCommand): string {
  return `// Generated by cf-loom ${command}. Do not edit.`;
}

/** An import of named exports. */
export function namedImportOf(names: readonly string[], specifier: string): string {
  return `import { ${names.join(', ')} } from ${stringLiteralOf(specifier)};`;
}

/** An import of a whole module under one name. */
export function namespaceImportOf(local: string, specifier: string): string {
  return `import * as ${local} from ${stringLiteralOf(specifier)};`;
}

/** An import of a module's default export under a local name. */
export function defaultImportOf(local: string, specifier: string): string {
  return `import ${local} from ${stringLiteralOf(specifier)};`;
}

/**
 * The relative specifier from one file to another, both relative to the same folder, naming the
 * `.ts` file, as Node's type stripping and `tsc`'s rewriting require.
 */
export function relativeSpecifierOf(from: string, to: string): string {
  const relative = posix.relative(posix.dirname(from), to);
  return relative.startsWith('.') ? relative : `./${relative}`;
}

/** What a generated module holds: its first lines, its imports in order, then its body. */
export type ModuleParts = {
  readonly first: readonly string[];
  readonly imports: readonly string[];
  readonly body: readonly string[];
};

/** A module's text: its first lines and imports, a blank line after imports, its body, a final newline. */
export function moduleTextOf({ first, imports, body }: ModuleParts): string {
  const head = [...first, ...imports];
  const parts = imports.length === 0 ? [...head, ...body] : [...head, '', ...body];
  return `${parts.join('\n')}\n`;
}
